<script setup>
import { computed, ref } from 'vue';
import { audiencePayload, audienceToForm } from '../../../domain/marketing.js';
import Icon from '../../ui/EditionIcon.vue';
import Modal from '../../ui/EditionModal.vue';

const props=defineProps({audiences:{type:Array,default:()=>[]},customers:{type:Array,default:()=>[]},canManage:Boolean,canWorkspaceManage:Boolean,busy:Boolean,error:{type:String,default:''}});
const emit=defineEmits(['save']);
const editor=ref(null),localError=ref(''),query=ref('');
const blank=()=>({name:'',description:'',workspace:false,consentRequired:false,consentChannels:[],studentStatus:'any',accountRequired:false,minOrderCount:'',minSpend:'',minLoyaltyPoints:'',lastPurchaseWithinDays:'',includeCustomerIds:[],excludeCustomerIds:[]});
const filteredCustomers=computed(()=>{const q=query.value.trim().toLowerCase();return props.customers.filter(row=>!q||[row.displayName,row.email,row.primaryEmail,row.phone].some(value=>String(value||'').toLowerCase().includes(q))).slice(0,30);});
const customerId=row=>row.customerId||row.id;
const audienceRuleSummary=row=>{const rules=[];if(row.customer?.accountRequired)rules.push('account holders');if(row.customer?.minOrderCount)rules.push(`${row.customer.minOrderCount}+ orders`);if(row.customer?.minSpendSen)rules.push(`RM ${(row.customer.minSpendSen/100).toFixed(2)}+ spend`);if(row.customer?.minLoyaltyPoints)rules.push(`${row.customer.minLoyaltyPoints}+ points`);if(row.customer?.lastPurchaseWithinDays)rules.push(`purchased within ${row.customer.lastPurchaseWithinDays} days`);if(row.eligibility?.studentStatus==='verified')rules.push('verified eligibility');return rules.join(' · ')||'All customers in scope';};
function open(row=null){editor.value=row?audienceToForm(row):blank();localError.value='';query.value='';}
function toggle(field,id){const values=new Set(editor.value[field]||[]);values.has(id)?values.delete(id):values.add(id);editor.value[field]=[...values];const other=field==='includeCustomerIds'?'excludeCustomerIds':'includeCustomerIds';if(values.has(id))editor.value[other]=(editor.value[other]||[]).filter(value=>value!==id);}
function save(){try{const payload=audiencePayload(editor.value,{workspace:editor.value.workspace});localError.value='';emit('save',{id:editor.value.id,payload,done:()=>editor.value=null});}catch(error){localError.value=error.message;}}
</script>

<template>
  <section class="mf-audience-panel">
    <div class="ed-section-head"><div><div class="ed-eyebrow">AUDIENCE BUILDER</div><h2>Reusable customer groups</h2><small>Rules are evaluated at qualification time. Consent criteria are saved for future delivery; no outbound sender is configured yet.</small></div><button v-if="canManage" class="ed-btn primary" @click="open()"><Icon name="plus"/>New audience</button></div>
    <div class="mf-audience-grid"><article v-for="row in audiences" :key="row.id"><header><span class="ed-pill">{{ row.scope==='workspace'?'Workspace':'Company' }}</span><span>Version {{ row.version }}</span></header><h3>{{ row.name }}</h3><p>{{ row.description||'No description.' }}</p><strong>{{ audienceRuleSummary(row) }}</strong><small v-if="row.consent?.required">Consent required: {{ row.consent.channels?.join(', ')||'selected channel' }}</small><button v-if="canManage&&(row.scope!=='workspace'||canWorkspaceManage)" class="ed-btn small" @click="open(row)">Create new version</button></article></div>
    <div v-if="!audiences.length" class="ed-empty"><Icon name="people"/><h3>No saved audiences.</h3><p>Campaigns can target everyone, or you can save a company audience from account, purchase, loyalty, consent and eligibility rules.</p></div>

    <Modal v-if="editor" :title="editor.id?'Create audience version':'Create audience'" wide :busy="busy" @close="editor=null">
      <form id="audience-form" class="mf-audience-form" @submit.prevent="save"><div class="ed-form-grid"><label class="ed-field"><span>Name</span><input v-model.trim="editor.name" required maxlength="120" placeholder="Regular lunch customers"></label><label class="ed-field"><span>Scope</span><select v-model="editor.workspace" :disabled="!canWorkspaceManage"><option :value="false">This company</option><option :value="true">Entire workspace</option></select><small v-if="!canWorkspaceManage">Managers create company audiences.</small></label><label class="ed-field wide"><span>Description</span><textarea v-model.trim="editor.description" maxlength="500" rows="2" placeholder="Who belongs here and why"></textarea></label></div>
        <fieldset><legend>Behaviour</legend><div class="ed-form-grid"><label class="mf-check"><input v-model="editor.accountRequired" type="checkbox">Registered account required</label><span></span><label class="ed-field"><span>Minimum orders</span><input v-model="editor.minOrderCount" type="number" min="1" step="1" placeholder="Any"></label><label class="ed-field"><span>Minimum lifetime spend (RM)</span><input v-model="editor.minSpend" inputmode="decimal" placeholder="Any"></label><label class="ed-field"><span>Minimum loyalty points</span><input v-model="editor.minLoyaltyPoints" type="number" min="1" step="1" placeholder="Any"></label><label class="ed-field"><span>Purchased within days</span><input v-model="editor.lastPurchaseWithinDays" type="number" min="1" step="1" placeholder="Any time"></label></div></fieldset>
        <fieldset><legend>Consent & eligibility</legend><div class="ed-form-grid"><label class="mf-check"><input v-model="editor.consentRequired" type="checkbox">Require marketing consent</label><label class="ed-field"><span>Eligibility</span><select v-model="editor.studentStatus"><option value="any">Any eligibility</option><option value="verified">Verified eligibility</option><option value="not_verified">Not verified</option></select></label></div><div v-if="editor.consentRequired" class="mf-inline-checks"><label v-for="channel in ['email','sms','whatsapp']" :key="channel"><input v-model="editor.consentChannels" type="checkbox" :value="channel">{{ channel }}</label></div></fieldset>
        <fieldset><legend>Specific customers · optional</legend><label class="ed-field"><span>Find a registered customer</span><input v-model="query" placeholder="Name, email or phone"></label><div class="mf-customer-picker"><article v-for="customer in filteredCustomers" :key="customerId(customer)"><span><strong>{{ customer.displayName||customer.email }}</strong><small>{{ customer.email||customer.primaryEmail||'Registered account' }}</small></span><button type="button" :class="{selected:editor.includeCustomerIds.includes(customerId(customer))}" @click="toggle('includeCustomerIds',customerId(customer))">{{ editor.includeCustomerIds.includes(customerId(customer))?'Included':'Include' }}</button><button type="button" :class="{excluded:editor.excludeCustomerIds.includes(customerId(customer))}" @click="toggle('excludeCustomerIds',customerId(customer))">{{ editor.excludeCustomerIds.includes(customerId(customer))?'Excluded':'Exclude' }}</button></article><p v-if="!customers.length" class="ed-muted">No registered customer profile is available for a direct selection.</p></div></fieldset>
      </form><p v-if="localError||error" class="ed-notice error" role="alert">{{ localError||error }}</p><template #actions><button class="ed-btn" :disabled="busy" @click="editor=null">Cancel</button><button class="ed-btn primary" type="submit" form="audience-form" :disabled="busy">{{ busy?'Saving…':'Save audience version' }}</button></template>
    </Modal>
  </section>
</template>

<style scoped>
.mf-audience-panel{display:grid;gap:20px}.mf-audience-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.mf-audience-grid article{border:1px solid var(--ed-line);background:var(--ed-paper);padding:18px;display:grid;gap:11px}.mf-audience-grid header{display:flex;justify-content:space-between;align-items:center;color:var(--ed-muted);font-size:9px}.mf-audience-grid h3{font:400 23px var(--ed-font-sans);margin:0}.mf-audience-grid p,.mf-audience-grid small{font-size:10px;color:var(--ed-muted);line-height:1.45;margin:0}.mf-audience-grid strong{font-size:11px;line-height:1.45}.mf-audience-grid button{justify-self:start}.mf-audience-form{display:grid;gap:18px}.mf-audience-form fieldset{border:1px solid var(--ed-line);padding:16px}.mf-audience-form legend{padding:0 7px;font-size:10px;letter-spacing:.08em;text-transform:uppercase}.mf-inline-checks{display:flex;gap:16px;margin-top:13px}.mf-inline-checks label,.mf-check{display:flex;align-items:center;gap:7px;font-size:11px;text-transform:capitalize}.mf-customer-picker{max-height:230px;overflow:auto;margin-top:12px}.mf-customer-picker article{display:grid;grid-template-columns:1fr auto auto;gap:8px;align-items:center;border-top:1px solid var(--ed-line);padding:10px 0}.mf-customer-picker span{display:grid}.mf-customer-picker small{font-size:9px;color:var(--ed-muted)}.mf-customer-picker button{border:1px solid var(--ed-line);background:var(--ed-paper);padding:7px 9px;font-size:9px}.mf-customer-picker button.selected{border-color:#3d8a66;background:#e9f7ee;color:#17603b}.mf-customer-picker button.excluded{border-color:#b95643;background:#fff0ed;color:#803b2e}@media(max-width:850px){.mf-audience-grid{grid-template-columns:1fr}.mf-customer-picker article{grid-template-columns:1fr auto}.mf-customer-picker span{grid-column:1/-1}}
</style>
